 "command": "git ls-files && cat src/flags.py src/billing/refunds.py; find . -name \"flags.toml\" -not -path \"./.git/*\" | xargs -I{} sh -c 'echo \"== {}\"; cat {}'",
 "description": "List files and show flag and refund code"
}

{
 "command": "grep -rn \"is_on\\|flags\" src tests scripts; cat src/api/errors.py; grep -rn \"refund\" src tests",
 "description": "Find existing flag usages and refund callers"
}

{
 "command": "printf 'bulk-refunds = false\n' >> flags.toml && cat > src/billing/refunds.py <<'EOF'
from .. import flags
from .invoices import Invoice


def refund(invoice: Invoice, amount_cents: int):
    if not flags.is_on("bulk-refunds"):
        raise RuntimeError("refunds are disabled (bulk-refunds flag is off)")
    if amount_cents > invoice.subtotal_cents + invoice.tax_cents:
        raise ValueError("refund exceeds invoice total")
    return {"invoice_id": invoice.id, "refunded_cents": amount_cents}
EOF
cat flags.toml; python -c "from src import flags; from src.billing import refunds; print(flags.is_on('bulk-refunds'))"; cat Makefile | grep -A2 test",
 "description": "Declare flag, gate refund(), sanity check import"
}

{
 "command": "python -c \"from src import flags; print(flags.is_on('bulk-refunds'), flags.all_flags())\"; git diff --stat",
 "description": "Verify flag loads from TOML"
}
